"use client";

import React, { useRef, useEffect, useCallback } from "react";
import { CATEGORIES } from "@/data/mockData";

/** Original reference embedded once: no image download or public-folder setup needed.
 * Only the illustration portion is displayed; headings and labels remain live text.
 * You can replace this with a local asset URL if your CSP does not allow data images.
 */
const REFERENCE_IMAGE = "data:image/png;base64,";

const ARTWORK_X: Record<string, number> = {
  internships: 171,
  jobs: 336,
  competitions: 501,
  "mock-tests": 667,
  "mock-interviews": 831,
  hackathons: 996,
  mentorships: 1161,
};

export const HeroHeader: React.FC = () => (
  <div className="mx-auto mb-3 flex w-full min-w-0 max-w-[980px] flex-col items-start justify-between gap-2.5 px-2 sm:flex-row sm:items-center sm:gap-4 sm:px-4">
    <h1 className="m-0 text-[clamp(26px,6vw,34px)] leading-[1.15] font-extrabold tracking-[-1px] text-[#111111] sm:text-[clamp(32px,3.6vw,40px)] min-[1001px]:text-[44px] min-[1001px]:tracking-[-1.4px] [&>span]:text-[#0073e6]">
      Unlock Your <span>Career!</span>
    </h1>
    <div className="box-border flex h-[28px] shrink-0 items-center gap-[6px] whitespace-nowrap rounded-[7px] bg-[linear-gradient(90deg,#ece3ff,rgba(246,242,255,0))] pr-[9px] pl-4 text-[12px] text-[#5130dc] [clip-path:polygon(0_0,100%_0,100%_100%,10px_100%)] sm:h-[30px] sm:text-[13px] [&_strong]:font-bold">
      <svg aria-hidden="true" width="20" height="22" viewBox="0 0 24 24">
        <path fill="#6240df" d="M9 2h9l-5 8h7L8 23l3-10H5z" />
        <path fill="#4121b7" d="M13 2h5l-5 8h7L8 23l7-13h-5z" />
      </svg>
      <span>Access to <strong>32M+</strong> profiles</span>
    </div>
  </div>
);

export interface CategoryCardsProps {
  selectedCategory: string;
  onSelectCategory: (categoryId: string) => void;
}

export const CategoryCards: React.FC<CategoryCardsProps> = ({ selectedCategory, onSelectCategory }) => {
  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const isDraggingRef = useRef(false);
  const startXRef = useRef(0);
  const scrollLeftRef = useRef(0);
  const hasMovedRef = useRef(false);
  const singleSetWidthRef = useRef(0);

  // Tripled categories to allow endless, continuous smooth sliding in both directions
  const displayCategories = [
    ...CATEGORIES.slice(0, 7).map((c, i) => ({ ...c, uniqueKey: `${c.id}-0-${i}` })),
    ...CATEGORIES.slice(0, 7).map((c, i) => ({ ...c, uniqueKey: `${c.id}-1-${i}` })),
    ...CATEGORIES.slice(0, 7).map((c, i) => ({ ...c, uniqueKey: `${c.id}-2-${i}` })),
  ];

  // Initialize scroll position to the middle set (set 1)
  useEffect(() => {
    const container = scrollContainerRef.current;
    if (!container) return;

    const firstCard = container.querySelector('button') as HTMLElement | null;
    if (firstCard) {
      const cardSpan = firstCard.offsetWidth + 6;
      singleSetWidthRef.current = cardSpan * 7;
      container.scrollLeft = singleSetWidthRef.current;
    }
  }, []);

  // Mouse wheel listener: converts vertical mouse wheel scroll directly to horizontal card sliding
  useEffect(() => {
    const container = scrollContainerRef.current;
    if (!container) return;

    const handleWheel = (e: WheelEvent) => {
      if (e.deltaY !== 0 || e.deltaX !== 0) {
        e.preventDefault();
        const delta = Math.abs(e.deltaY) >= Math.abs(e.deltaX) ? e.deltaY : e.deltaX;
        container.scrollLeft += delta * 1.1;
      }
    };

    container.addEventListener("wheel", handleWheel, { passive: false });
    return () => container.removeEventListener("wheel", handleWheel);
  }, []);

  // Seamless wrap-around scroll listener
  const handleScroll = useCallback(() => {
    const container = scrollContainerRef.current;
    if (!container || singleSetWidthRef.current === 0) return;

    const setWidth = singleSetWidthRef.current;
    if (container.scrollLeft >= setWidth * 2 - 10) {
      container.scrollLeft -= setWidth;
    } else if (container.scrollLeft <= 10) {
      container.scrollLeft += setWidth;
    }
  }, []);

  // Mouse drag handlers
  const handleMouseDown = (e: React.MouseEvent) => {
    const container = scrollContainerRef.current;
    if (!container) return;
    isDraggingRef.current = true;
    hasMovedRef.current = false;
    startXRef.current = e.pageX - container.offsetLeft;
    scrollLeftRef.current = container.scrollLeft;
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!isDraggingRef.current) return;
    const container = scrollContainerRef.current;
    if (!container) return;
    e.preventDefault();
    const x = e.pageX - container.offsetLeft;
    const walk = (x - startXRef.current) * 1.3;
    if (Math.abs(walk) > 4) {
      hasMovedRef.current = true;
    }
    container.scrollLeft = scrollLeftRef.current - walk;
  };

  const handleMouseUp = () => {
    isDraggingRef.current = false;
    setTimeout(() => {
      hasMovedRef.current = false;
    }, 50);
  };

  const handleCardClick = (catId: string) => {
    if (hasMovedRef.current) return;
    onSelectCategory(catId);
  };

  return (
    <div
      className="relative mx-auto w-full min-w-0 max-w-[980px] px-2 sm:px-4"
      onMouseLeave={handleMouseUp}
    >
      {/* Left White Shine */}
      <div
        aria-hidden="true"
        className="pointer-events-none absolute left-0 top-0 bottom-0 z-20 w-8 sm:w-14 md:w-16"
        style={{
          background: 'linear-gradient(to right, #ffffff 0%, rgba(255, 255, 255, 0.95) 30%, rgba(255, 255, 255, 0) 100%)',
        }}
      />
      {/* Right White Shine */}
      <div
        aria-hidden="true"
        className="pointer-events-none absolute right-0 top-0 bottom-0 z-20 w-8 sm:w-14 md:w-16"
        style={{
          background: 'linear-gradient(to left, #ffffff 0%, rgba(255, 255, 255, 0.95) 30%, rgba(255, 255, 255, 0) 100%)',
        }}
      />

      <div
        ref={scrollContainerRef}
        onScroll={handleScroll}
        onMouseDown={handleMouseDown}
        onMouseMove={handleMouseMove}
        onMouseUp={handleMouseUp}
        className="flex items-center gap-[6px] overflow-x-auto overflow-y-hidden overscroll-x-contain py-1.5 [scrollbar-width:none] [&::-webkit-scrollbar]:hidden motion-safe:scroll-smooth cursor-grab active:cursor-grabbing select-none"
        role="group"
        aria-label="Career categories"
      >
        {displayCategories.map((cat) => {
          const type = String(cat.iconType);
          const artworkX = ARTWORK_X[type];
          const hasReference = artworkX !== undefined;

          return (
            <button
              key={cat.uniqueKey}
              type="button"
              className="relative isolate box-border h-[134px] w-[124px] shrink-0 snap-start cursor-pointer overflow-hidden rounded-[26px] border-0 bg-[#e9f4ff] p-0 font-[inherit] text-[#161616] [-webkit-tap-highlight-color:transparent] shadow-none hover:shadow-none transition-transform duration-200 ease-out hover:-translate-y-1.5 hover:brightness-[0.98] outline-none focus:outline-none focus-visible:outline-none ring-0 focus:ring-0"
              aria-pressed={selectedCategory === cat.id}
              onClick={() => handleCardClick(cat.id)}
            >
              <svg className="pointer-events-none absolute inset-0 -z-10 h-full w-full" viewBox="0 0 152 164" preserveAspectRatio="none" aria-hidden="true">
                <rect width="152" height="164" fill="#ddeeff" />
                <path d="M0 0H152C137 45 118 78 90 101C65 120 32 124 0 124Z" fill="#e9f4ff" />
              </svg>
              <span className="absolute inset-x-[4px] top-3.5 z-[2] text-center text-[14px] leading-[15px] font-semibold tracking-[-0.3px]">
                {type === "mock-interviews" || cat.id === "mock-interviews" ? <>Mock<br />Interviews</> : cat.title}
              </span>
              {hasReference ? (
                <svg
                  className="pointer-events-none absolute bottom-0 left-0 h-[78px] w-[124px] overflow-hidden"
                  viewBox="0 0 152 97"
                  aria-hidden="true"
                  focusable="false"
                >
                  <image href={REFERENCE_IMAGE} x={-artworkX} y={-174} width={1547} height={296} />
                </svg>
              ) : (
                <span className="pointer-events-none absolute left-[26px] top-[66px] scale-[1.05]" aria-hidden="true">
                  <svg width="76" height="58" viewBox="0 0 76 58" fill="none">
                    <rect x="18" y="10" width="40" height="38" rx="9" fill="#7357e8" />
                    <circle cx="38" cy="29" r="13" stroke="white" strokeWidth="3" />
                    <circle cx="38" cy="29" r="6" stroke="white" strokeWidth="3" />
                    <path d="M38 29 57 10m-6 0h6v6" stroke="#facc15" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" />
                  </svg>
                </span>
              )}
              {(type === "mock-tests" || !hasReference) && (
                <svg className="pointer-events-none absolute left-[10px] top-[34px] h-[22px] w-[17px]" viewBox="0 0 26 32" aria-hidden="true">
                  <path fill="#427bff" d="M7 0l1.8 4.8L14 7l-5.2 1.8L7 14 5 8.8 0 7l5-2.2z" />
                  <path fill="#a768ff" d="M13 10l2.8 7.2L23 20l-7.2 2.8L13 30l-2.8-7.2L3 20l7.2-2.8z" />
                  <path fill="#6c9bff" d="M22 2l1 3 3 1-3 1-1 3-1-3-3-1 3-1z" />
                </svg>
              )}
            </button>
          );
        })}
      </div>
    </div>
  );
};

export type HeroProps = CategoryCardsProps;

/** Next.js client component. All layout and responsive styling use Tailwind CSS.
 * Render inside a min-w-0 content column if the page also has a sidebar.
 */
export const Hero: React.FC<HeroProps> = ({ selectedCategory, onSelectCategory }) => (
  <section className="mx-auto box-border w-full min-w-0 max-w-[980px] bg-white py-4 px-2 sm:px-4 [font-family:Arial,Helvetica,sans-serif] sm:pt-[22px] sm:pb-[18px]" aria-label="Unlock your career">
    <HeroHeader />
    <CategoryCards selectedCategory={selectedCategory} onSelectCategory={onSelectCategory} />
  </section>
);

export default Hero;
